#!/usr/bin/env python3
"""Verify every glyph in the two full-SC inputs generated by benches/woff.py."""
import argparse,json,hashlib,time
from pathlib import Path
from woff import invoke,equivalent
from glyf import bitmap,shape
import freetype,ots
from fontTools.ttLib import TTFont
from fontTools.ttLib.woff2 import WOFF2GlyfTable

def main():
    p=argparse.ArgumentParser();p.add_argument('--binary',type=Path,required=True);p.add_argument('--work',type=Path,required=True);p.add_argument('--output',type=Path,required=True);p.add_argument('--oracle-zero-copy',action='store_true');a=p.parse_args();results=[]
    if a.oracle_zero_copy:
        original=WOFF2GlyfTable._decodeComponents
        def components_without_tail_copy(self,glyph):
            self.compositeStream=memoryview(self.compositeStream)
            return original(self,glyph)
        # Keep the original algorithm, parsing and checks. Only replace repeated
        # immutable whole-tail copies by zero-copy read-only buffer slices.
        WOFF2GlyfTable._decodeComponents=components_without_tail_copy
        print('fontTools oracle uses read-only composite-stream memoryviews; not a stock-fontTools benchmark',flush=True)
    for source in [a.work/'Tong-SC-square.otf',a.work/'Tong-SC-dot.ttf']:
        started=time.perf_counter();label=source.stem;web=source.with_suffix('.validation.woff2');out=source.with_suffix('.validation.sfnt');sanitized=source.with_suffix('.validation.ots.sfnt')
        invoke(a.binary,'encode','woff2',source,web,5,4);print(label,'encoded',flush=True)
        assert TTFont(web)['head'].flags & 0x800,(label,'required WOFF2 head flag')
        count=equivalent(source,web,label,True);print(label,'fontTools and FreeType all glyphs passed',count,flush=True)
        invoke(a.binary,'decode','woff2',web,out);equivalent(source,out,label,False)
        status=ots.sanitize(str(web),str(sanitized),capture_output=True);assert status.returncode==0,status.stderr
        left,right=freetype.Face(str(source)),freetype.Face(str(sanitized))
        for gid in range(left.num_glyphs):assert bitmap(left,gid)==bitmap(right,gid),(label,gid,'OTS')
        text=''.join(chr(c) for c in TTFont(source).getBestCmap())
        for language in ['zh-Hans','zh-Hant','zh-HK','ja','ko','en']:assert shape(source.read_bytes(),text,language)==shape(out.read_bytes(),text,language),(label,language)
        results.append({'font':label,'glyphs':count,'quality':5,'compression_threads':4,'oracle_zero_copy':a.oracle_zero_copy,'validation_seconds':time.perf_counter()-started,'fontTools':'all glyphs/tables equal','FreeType':'all glyphs equal','OTS':'accepted, all glyphs equal','HarfBuzz':'all cmap characters, 6 languages equal'})
        print(label,'complete',flush=True)
    a.output.write_text(json.dumps(results,indent=2)+'\n')
if __name__=='__main__':main()
